#include <iostream>
int main() {
    int a = 7, b = 2;
    std::cout << a / b << ' ' << (double)a / b << ' ' << a % b << '\n'; // 3 3.5 1
}

#include <iostream>
int main() {
    int* ptr = nullptr;
    // An toàn nhờ Short-circuit: ptr != nullptr sai nên vế sau không chạy
    if (ptr != nullptr && *ptr == 10) {
        std::cout << "OK\n";
    }
}

#include <iostream>
int main() {
    int n = 6; // 110 trong nhị phân
    std::cout << (n << 1) << ' ' << (n >> 1) << '\n'; // 12 và 3
}

#include <iostream>
int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    size_t len = sizeof(arr) / sizeof(arr[0]);
    std::cout << "So phan tu: " << len << '\n';
}
